const session = data.session;
const skipBackendOAuthBridge =
  process.env.NODE_ENV !== 'production' &&
  process.env.NEXT_PUBLIC_SKIP_BACKEND_OAUTH_BRIDGE !== 'false';

const createSupabaseFallbackResponse = (reason: string): NextResponse | null => {
  if (!session?.access_token || !session?.refresh_token) {
    return null;
  }

  const successResponse = NextResponse.redirect(new URL(redirectPath, origin));
  const cookieOpts = {
    path: '/',
    maxAge: 60,
    httpOnly: false,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax' as const,
  };

  const payload = {
    accessToken: session.access_token,
    refreshToken: session.refresh_token ?? '',
    user: {
      id: supaUser.id,
      email,
      role: 'learner',
      ...(firstName ? { firstName } : {}),
      ...(lastName ? { lastName } : {}),
    },
  };

  successResponse.cookies.set('oauth_payload', JSON.stringify(payload), cookieOpts);
  successResponse.cookies.set('oauth_warning', reason, cookieOpts);
  return successResponse;
};

if (skipBackendOAuthBridge) {
  const fallbackResponse = createSupabaseFallbackResponse('backend_bridge_skipped');
  if (fallbackResponse) {
    console.warn('[auth/callback] skipping backend OAuth bridge by environment flag');
    return fallbackResponse;
  }
}

 * Revokes a cookie application session and records the same transactional
 * security audit emitted by the legacy bearer logout path.
 */
export async function revokeApplicationSession(c: Context<Env>): Promise<void> {
  const sessionToken = getApplicationSessionToken(c);
  if (sessionToken === undefined || sessionToken.length === 0) {
    deleteCookie(c, APPLICATION_SESSION_COOKIE, deleteCookieOptions(c));
    return;
  }

  const db = getDatabase();
  await db.transaction(async (tx) => {
    const session = await tx.query.authSessions.findFirst({
      where: and(eq(authSessions.token, sessionToken), isNull(authSessions.revokedAt)),
      with: { user: true },
    });
    if (session === undefined) {
      return;
    }

    const [revoked] = await tx
      .update(authSessions)
      .set({ revokedAt: new Date() })
      .where(and(eq(authSessions.id, session.id), isNull(authSessions.revokedAt)))
      .returning({ id: authSessions.id });
    if (revoked === undefined) {
      return;
    }

    await insertAuditLogInTransaction(tx, {
      ...(session.user.organizationId !== null
        ? { organizationId: session.user.organizationId }
        : {}),
      requestId: c.get('requestId'),
      userId: session.user.id,
      action: 'auth.logout',
      resource: 'auth_session',
      resourceId: revoked.id,
      eventKind: 'transactional-audit',
      ipAddress: clientIpAddress(c.req.header('x-vercel-forwarded-for')),
      userAgent: c.req.header('user-agent') ?? undefined,
    });
  });

  deleteCookie(c, APPLICATION_SESSION_COOKIE, deleteCookieOptions(c));
}

function isJsonResponse(response: Response): boolean {
  return response.headers.get('content-type')?.toLowerCase().includes('application/json') === true;
}

/**
 * Enforce the shared operation registry after authentication. The authenticated subject is the
 * only JWT-derived input; current role, organization, membership, and location are reloaded from
 * PostgreSQL before the request may reach a protected handler.
 */
export async function authorizeRegisteredOperation(c: Context<Env>): Promise<void> {
  const operationPath = canonicalOperationPath(c.req.path);
  if (operationPath === null) {
    throw new AuthorizationError('Protected operation is not registered');
  }
  const operation = findProtectedApiOperation(c.req.method, operationPath);
  if (operation === undefined) {
    throw new AuthorizationError('Protected operation is not registered');
  }
  const parameters = routeParameters(operation, operationPath);
  if (
    parameters === null ||
    !scopedUuidParametersAreValid(operation, parameters) ||
    !(await requestScopedUuidFieldsAreValid(c, operation))
  ) {
    throw notFound('Resource');
  }

  const db = getDatabase();
  const actorId = c.get('userId');
  const actor = await resolveAuthoritativeActor(actorId, db);
  if (actor === null) {
    throw new AuthenticationError('Invalid account');
  }

