    return true;
  }

  return prerelease.split('.').every(isPrereleaseIdentifier);
}

export function kindOf(token: string): VersionTokenKind | null {
  if (SPEC_RE.test(token)) return 'spec';
  if (token.startsWith('s') && isSemanticVersionToken(token.slice(1))) return 'schema';
  if (token.startsWith('v') && isSemanticVersionToken(token.slice(1))) return 'pack';
  return null;
}
